function safeClone(obj) {
  return typeof structuredClone === 'function'
    ? structuredClone(obj)
    : JSON.parse(JSON.stringify(obj));
}

// Old versions of the seed data — cleared automatically on first load of a new
// version so switching demo-data versions never leaves stale, mismatched data
// (old teacher IDs, old passwords) sitting in a person's browser.
const OLD_DB_KEYS = ['workforce_db_v1', 'workforce_db_v2', 'workforce_db_v3', 'workforce_db_v4', 'campuspass_db_v1'];

function seedCourseClassRosters(db) {
  const students = Array.isArray(db.students) ? db.students : [];
  const enrollments = Array.isArray(db.enrollments) ? db.enrollments : [];
  (db.courseClasses || []).forEach((cc) => {
    // Only seed the bundled demo course classes. Never overwrite a roster a user has edited.
    if (!['cc1', 'cc2', 'cc3', 'cc4', 'cc5', 'cc6'].includes(cc.id)) return;
    if (Array.isArray(cc.studentIds) && cc.studentIds.length) return;
    const enrolled = enrollments.filter((e) => e.courseClassId === cc.id).map((e) => e.studentId);
    if (enrolled.length) {
      cc.studentIds = [...new Set(enrolled)];
      return;
    }
    const groups = cc.groups || [];
    cc.studentIds = students
      .filter((s) => classKeyOf(s) === cc.classKey && (!groups.length || groups.includes(s.group)))
      .map((s) => s.id);
  });
}

function readDb() {
  try {
    const raw = localStorage.getItem(DB_KEY);
    if (!raw) {
      // Recover a previously saved app database before creating fresh demo data.
      const backupRaw = localStorage.getItem(BACKUP_DB_KEY);
      if (backupRaw) {
        const backup = JSON.parse(backupRaw);
        if (backup && typeof backup === 'object' && Array.isArray(backup.students) && Array.isArray(backup.teachers)) {
          writeDb(backup);
          return backup;
        }
      }
      OLD_DB_KEYS.filter((k) => k !== DB_KEY).forEach((k) => localStorage.removeItem(k));
      const db = safeClone(DEFAULT_DB);
      seedCourseClassRosters(db);
      writeDb(db);
      return db;
    }
    const db = JSON.parse(raw);
    // Lightweight migration for browsers that already had v4 data saved.
    if (!Array.isArray(db.admins)) db.admins = safeClone(DEFAULT_DB.admins);
    // Remove the old demo content-manager account from existing v4 browsers.
    const cleanedAdmins = db.admins.filter((a) => a.id !== 'A001').slice(0, 1);
    const adminsChanged = JSON.stringify(cleanedAdmins) !== JSON.stringify(db.admins);
    db.admins = cleanedAdmins;
    if (!Object.prototype.hasOwnProperty.call(db, 'rememberedLogin')) db.rememberedLogin = null;
    if (!Array.isArray(db.courseClasses)) db.courseClasses = [];
    if (!Array.isArray(db.enrollments)) db.enrollments = [];

    // Ensure every teacher who already has a class assignment also has at least
    // one usable Course Class. Older accounts stored only the broad class key,
    // which made the Add Students / Attendance pages appear empty.
    (db.teachers || []).forEach((teacher) => {
      const assigned = Array.isArray(teacher.classes) ? teacher.classes : [];
      const hasCourseClass = db.courseClasses.some((cc) => cc.teacherId === teacher.id);
      if (!hasCourseClass && assigned.length) {
        const classKey = assigned[0];
        const course = subjectsForClass(classKey)[0] || 'Data Structures';
        db.courseClasses.push({
          id: `cc_${teacher.id.toLowerCase()}_${Date.now().toString(36)}`,
          teacherId: teacher.id, classKey, course, section: 'A',
          groups: Array.isArray(teacher.groups) ? [...teacher.groups] : [], studentIds: []
        });
      }
    });
    // Existing v3 browsers may have the bundled course classes without an exact roster.
    // Seed those demo rosters once; user-created/edited course classes are never touched.
    if (!db.courseRosterMigrationV2) {
      seedCourseClassRosters(db);
      db.courseRosterMigrationV2 = true;
      writeDb(db);
    } else if (adminsChanged) {
      // Persist the demo-account cleanup so it stays removed after a refresh.
      writeDb(db);
    }
    return db;
  } catch (e) {
    console.error('Store read failed', e);
    return safeClone(DEFAULT_DB);
  }
}

function writeDb(db) {
  const serialized = JSON.stringify(db);
  localStorage.setItem(DB_KEY, serialized);
  // Keep a second copy so an accidental storage reset/corruption does not wipe
  // user-created accounts and course data on the next page load.
  localStorage.setItem(BACKUP_DB_KEY, serialized);
}

export const Store = {
  get(table) {
    return readDb()[table];
  },
  set(table, value) {
    const db = readDb();
    db[table] = value;
    writeDb(db);
  },
  push(table, item) {
    const db = readDb();
    if (!Array.isArray(db[table])) db[table] = [];
    db[table].push(item);
    writeDb(db);
    return item;
  },
  update(table, predicate, updater) {
    const db = readDb();
    const arr = db[table];
    if (!Array.isArray(arr)) return;
    const idx = arr.findIndex(predicate);
    if (idx !== -1) {
      arr[idx] = updater(arr[idx]);
      writeDb(db);
    }
  },
  remove(table, predicate) {
    const db = readDb();
    const arr = db[table];
    if (!Array.isArray(arr)) return;
    db[table] = arr.filter((item) => !predicate(item));
    writeDb(db);
  },
  session() {
    return readDb().session;
  },
  rememberedLogin() {
    return readDb().rememberedLogin;
  },
  setRememberedLogin(value) {
    const db = readDb();
    db.rememberedLogin = value;
    writeDb(db);
  },
  setSession(session) {
    const db = readDb();
    db.session = session;
    writeDb(db);
  },
  clearSession() {
    this.setSession(null);
  },
  reset() {
    writeDb(DEFAULT_DB);
  },
  uid(prefix = 'id') {
    return prefix + '_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 7);
  },
};

export function fmtDate(d) {
  try {
    return new Date(d).toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' });
  } catch {
    return d;
  }
}

/* ============================================
   Class / section scoping helpers
   A "class" is identified by a key like "CSE-2nd Year" — branch + year.
   Teachers are assigned to one or more classes; they should only see and
   manage students that belong to those classes.
   ============================================ */

export function classKeyOf(student) {
  if (!student) return '';
  return `${student.branch || 'Undeclared'}-${student.year || 'Undeclared'}`;
}

/** All class keys we currently know about (from student records + any timetable entries). */
export function allClassKeys() {
  const fromStudents = Store.get('students').map(classKeyOf);
  const fromTimetable = Object.keys(Store.get('timetable'));
  return [...new Set([...fromStudents, ...fromTimetable])].sort();
}

export const ALL_GROUPS = ['G1', 'G2', 'G3', 'G4', 'G5', 'G6', 'G7', 'G8', 'G9', 'G10'];

/** The class keys a given teacher is assigned to teach. */
export function getTeacherClasses(teacherId) {
  const teacher = Store.get('teachers').find((t) => t.id === teacherId);
  return teacher?.classes ?? [];
}

export function getTeacherGroups(teacherId) {
  const teacher = Store.get('teachers').find((t) => t.id === teacherId);
  return teacher?.groups ?? [];
}

export function studentsInClasses(classKeys) {
  if (!classKeys || classKeys.length === 0) return [];
  return Store.get('students').filter((s) => classKeys.includes(classKeyOf(s)));
}

export function rosterForTeacher(teacherId) {
  const classRoster = studentsInClasses(getTeacherClasses(teacherId));
  const groups = getTeacherGroups(teacherId);
  if (!groups || groups.length === 0) return classRoster;
  return classRoster.filter((s) => groups.includes(s.group));
}

export function rosterForTeacherInClass(teacherId, classKey) {
  if (!classKey) return [];
  const classes = getTeacherClasses(teacherId);
  if (!classes.includes(classKey)) return [];
  const inClass = studentsInClasses([classKey]);
  const groups = getTeacherGroups(teacherId);
  if (!groups || groups.length === 0) return inClass;
  return inClass.filter((s) => groups.includes(s.group));
}

const CLASS_SUBJECTS = {
  'CSE-2nd Year': ['Data Structures', 'DBMS', 'Operating Systems', 'Maths III'],
  'CSE-3rd Year': ['Algorithms', 'Computer Networks', 'Operating Systems', 'Software Engineering'],
  'ECE-2nd Year': ['Circuit Theory', 'Electronic Devices', 'Maths III', 'Digital Logic Design'],
  'ECE-3rd Year': ['Signals & Systems', 'VLSI Design', 'Microprocessors', 'Communication Systems'],
  'IT-2nd Year': ['Data Structures', 'Web Technologies', 'Operating Systems', 'Maths III'],
};
const DEFAULT_SUBJECTS = ['Data Structures', 'DBMS', 'Operating Systems', 'Maths III'];

export function subjectsForClass(classKey) {
  return CLASS_SUBJECTS[classKey] || DEFAULT_SUBJECTS;
}

export function getTeacherCourseClasses(teacherId) {
  return (Store.get('courseClasses') || []).filter((cc) => cc.teacherId === teacherId);
}

export function courseClassLabel(cc) {
  if (!cc) return '';
  const groupLabel = cc.groups?.length === 1 ? ` · ${cc.groups[0]}` : '';
  const sectionLabel = cc.section ? ` · ${cc.section}` : '';
  return `${cc.classKey} · ${cc.course}${sectionLabel}${groupLabel}`;
}

export function courseClassGroups(courseClass) {
  if (!courseClass) return ALL_GROUPS;
  const explicit = Array.isArray(courseClass.groups) ? courseClass.groups.filter(Boolean) : [];
  if (explicit.length) return explicit;
  return ALL_GROUPS;
}

export function studentsForCourseClass(courseClass, selectedGroup = null) {
  if (!courseClass) return [];
  const students = Store.get('students') || [];
  const ids = new Set(Array.isArray(courseClass.studentIds) ? courseClass.studentIds : []);
  const enrollments = (Store.get('enrollments') || []).filter((e) => e.courseClassId === courseClass.id);
  enrollments.forEach((e) => ids.add(e.studentId));
  let result = students.filter((s) => ids.has(s.id));
  if (selectedGroup && selectedGroup !== 'All') {
    result = result.filter((s) => {
      const enrollment = enrollments.find((e) => e.studentId === s.id);
      return (enrollment?.group || s.group) === selectedGroup;
    });
  }
  return result;
}

export function getStudentCourseClasses(studentId) {
  if (!studentId) return [];
  return (Store.get('courseClasses') || []).filter((cc) => {
    if (Array.isArray(cc.studentIds) && cc.studentIds.includes(studentId)) return true;
    return (Store.get('enrollments') || []).some((e) => e.courseClassId === cc.id && e.studentId === studentId);
  });
}

/** Next unused sequential student ID, e.g. 'S261' if the highest existing is S260. */
export function nextStudentId() {
  const students = Store.get('students');
  const nums = students
    .map((s) => parseInt(String(s.id).replace(/\D/g, ''), 10))
    .filter((n) => !isNaN(n));
  const max = nums.length ? Math.max(...nums) : 100;
  return `S${max + 1}`;
}

